-- 04 | medium | Binary Tree Level Order Traversal
SELECT pg_temp.seed_coding($q$Trees$q$, 'medium', $q$Binary Tree Level Order Traversal$q$, $q$Print the values level by level, from the root downwards and left to right, one level per line. The tree is given in level order, with 'null' marking a missing child (the same format LeetCode uses); your function receives the root node.

Input Format:
- root: an integer n, then n space-separated tokens: the binary tree in level order, 'null' marks a missing child

Output Format:
Print each row on its own line, values separated by single spaces.

Example:
Input:
7
3 9 20 null null 15 7
Output:
3
9 20
15 7$q$,
  $q$def level_order(root: Optional[TreeNode]) -> List[List[int]]$q$, $j${"python":"import sys\nfrom typing import List, Optional\nfrom collections import deque\n\nclass TreeNode:\n    def __init__(self, val=0, left=None, right=None):\n        self.val = val\n        self.left = left\n        self.right = right\n\ndef level_order(root: Optional[TreeNode]) -> List[List[int]]:\n    # Write your solution here\n    pass\n\n\ndef build_tree(tokens):\n    if not tokens or tokens[0] == 'null':\n        return None\n    root = TreeNode(int(tokens[0]))\n    queue = deque([root])\n    i = 1\n    while queue and i < len(tokens):\n        node = queue.popleft()\n        if i < len(tokens) and tokens[i] != 'null':\n            node.left = TreeNode(int(tokens[i]))\n            queue.append(node.left)\n        i += 1\n        if i < len(tokens) and tokens[i] != 'null':\n            node.right = TreeNode(int(tokens[i]))\n            queue.append(node.right)\n        i += 1\n    return root\n\n\ndef main():\n    it = iter(sys.stdin.read().split())\n    root = build_tree([next(it) for _ in range(int(next(it)))])\n    result = level_order(root)\n    print('\\n'.join(' '.join(map(str, row)) for row in result))\n\n\nmain()\n","javascript":"const tokens = require('fs').readFileSync(0, 'utf8').split(/\\s+/).filter(Boolean);\nlet pos = 0;\nconst next = () => tokens[pos++];\n\nclass TreeNode {\n  constructor(val = 0, left = null, right = null) {\n    this.val = val;\n    this.left = left;\n    this.right = right;\n  }\n}\n\nfunction levelOrder(root) {\n  // Write your solution here\n}\n\nfunction buildTree(tokens) {\n  if (tokens.length === 0 || tokens[0] === 'null') return null;\n  const root = new TreeNode(parseInt(tokens[0]));\n  const queue = [root];\n  let head = 0;\n  let i = 1;\n  while (head < queue.length && i < tokens.length) {\n    const node = queue[head++];\n    if (i < tokens.length && tokens[i] !== 'null') {\n      node.left = new TreeNode(parseInt(tokens[i]));\n      queue.push(node.left);\n    }\n    i++;\n    if (i < tokens.length && tokens[i] !== 'null') {\n      node.right = new TreeNode(parseInt(tokens[i]));\n      queue.push(node.right);\n    }\n    i++;\n  }\n  return root;\n}\n\nconst root = buildTree(Array.from({ length: parseInt(next()) }, () => next()));\nconst result = levelOrder(root);\nconsole.log(result.map((row) => row.join(' ')).join('\\n'));\n","java":"import java.util.*;\n\npublic class Main {\n    static class TreeNode {\n        int val;\n        TreeNode left, right;\n        TreeNode(int val) { this.val = val; }\n    }\n\n    static int[][] levelOrder(TreeNode root) {\n        // Write your solution here\n        return new int[0][];\n    }\n\n    static TreeNode buildTree(String[] tokens) {\n        if (tokens.length == 0 || tokens[0].equals(\"null\")) return null;\n        TreeNode root = new TreeNode(Integer.parseInt(tokens[0]));\n        Deque<TreeNode> queue = new ArrayDeque<>();\n        queue.add(root);\n        int i = 1;\n        while (!queue.isEmpty() && i < tokens.length) {\n            TreeNode node = queue.poll();\n            if (i < tokens.length && !tokens[i].equals(\"null\")) {\n                node.left = new TreeNode(Integer.parseInt(tokens[i]));\n                queue.add(node.left);\n            }\n            i++;\n            if (i < tokens.length && !tokens[i].equals(\"null\")) {\n                node.right = new TreeNode(Integer.parseInt(tokens[i]));\n                queue.add(node.right);\n            }\n            i++;\n        }\n        return root;\n    }\n\n    public static void main(String[] mainArgs) {\n        Scanner scanner = new Scanner(System.in);\n        String[] rootTokens = new String[scanner.nextInt()];\n        for (int i = 0; i < rootTokens.length; i++) rootTokens[i] = scanner.next();\n        TreeNode root = buildTree(rootTokens);\n        int[][] result = levelOrder(root);\n        StringBuilder sb = new StringBuilder();\n        for (int[] row : result) {\n            for (int j = 0; j < row.length; j++) {\n                if (j > 0) sb.append(' ');\n                sb.append(row[j]);\n            }\n            sb.append('\\n');\n        }\n        System.out.print(sb);\n    }\n}\n","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n\nstruct TreeNode {\n    int val;\n    TreeNode* left;\n    TreeNode* right;\n    TreeNode(int v) : val(v), left(nullptr), right(nullptr) {}\n};\n\nvector<vector<int>> levelOrder(TreeNode* root) {\n    // Write your solution here\n    return {};\n}\n\nTreeNode* buildTree(const vector<string>& tokens) {\n    if (tokens.empty() || tokens[0] == \"null\") return nullptr;\n    TreeNode* root = new TreeNode(stoi(tokens[0]));\n    queue<TreeNode*> q;\n    q.push(root);\n    size_t i = 1;\n    while (!q.empty() && i < tokens.size()) {\n        TreeNode* node = q.front();\n        q.pop();\n        if (i < tokens.size() && tokens[i] != \"null\") {\n            node->left = new TreeNode(stoi(tokens[i]));\n            q.push(node->left);\n        }\n        i++;\n        if (i < tokens.size() && tokens[i] != \"null\") {\n            node->right = new TreeNode(stoi(tokens[i]));\n            q.push(node->right);\n        }\n        i++;\n    }\n    return root;\n}\n\nint main() {\n    int rootN;\n    cin >> rootN;\n    vector<string> rootTokens(rootN);\n    for (string& x : rootTokens) cin >> x;\n    TreeNode* root = buildTree(rootTokens);\n    auto result = levelOrder(root);\n    for (auto& row : result) {\n        for (size_t j = 0; j < row.size(); j++) {\n            if (j) cout << ' ';\n            cout << row[j];\n        }\n        cout << '\\n';\n    }\n    return 0;\n}\n"}$j$::jsonb, $j$[{"input":"7\n3 9 20 null null 15 7","expected":"3\n9 20\n15 7"},{"input":"7\n1 2 3 4 null null 5","expected":"1\n2 3\n4 5"},{"input":"1\n7","expected":"7"},{"input":"8\n7 -3 null -9 null null -2 1","expected":"7\n-3\n-9\n-2\n1"},{"input":"9\n5 5 null 0 8 null null null -1","expected":"5\n5\n0 8\n-1"},{"input":"7\n7 3 9 null null 4 4","expected":"7\n3 9\n4 4"}]$j$::jsonb,
