r.nextInt();\n        int q = scanner.nextInt();\n        int result = lowestCommonAncestor(root, p, q);\n        System.out.println(result);\n    }\n}\n","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n\nstruct TreeNode {\n    int val;\n    TreeNode* left;\n    TreeNode* right;\n    TreeNode(int v) : val(v), left(nullptr), right(nullptr) {}\n};\n\nint lowestCommonAncestor(TreeNode* root, int p, int q) {\n    // Write your solution here\n    return 0;\n}\n\nTreeNode* buildTree(const vector<string>& tokens) {\n    if (tokens.empty() || tokens[0] == \"null\") return nullptr;\n    TreeNode* root = new TreeNode(stoi(tokens[0]));\n    queue<TreeNode*> q;\n    q.push(root);\n    size_t i = 1;\n    while (!q.empty() && i < tokens.size()) {\n        TreeNode* node = q.front();\n        q.pop();\n        if (i < tokens.size() && tokens[i] != \"null\") {\n            node->left = new TreeNode(stoi(tokens[i]));\n            q.push(node->left);\n        }\n        i++;\n        if (i < tokens.size() && tokens[i] != \"null\") {\n            node->right = new TreeNode(stoi(tokens[i]));\n            q.push(node->right);\n        }\n        i++;\n    }\n    return root;\n}\n\nint main() {\n    int rootN;\n    cin >> rootN;\n    vector<string> rootTokens(rootN);\n    for (string& x : rootTokens) cin >> x;\n    TreeNode* root = buildTree(rootTokens);\n    int p;\n    cin >> p;\n    int q;\n    cin >> q;\n    auto result = lowestCommonAncestor(root, p, q);\n    cout << result << endl;\n    return 0;\n}\n"}$j$::jsonb, $j$[{"input":"11\n3 5 1 6 2 0 8 null null 7 4\n5\n1","expected":"3"},{"input":"11\n3 5 1 6 2 0 8 null null 7 4\n5\n4","expected":"5"},{"input":"2\n1 2\n1\n2","expected":"1"},{"input":"16\n29 6 33 null 38 35 null 36 null 2 null null 32 34 null 12\n29\n38","expected":"29"},{"input":"9\n21 16 null 39 12 null null 3 11\n21\n39","expected":"21"},{"input":"16\n16 6 null 1 38 null 25 2 null null null null 14 30 null 20\n20\n1","expected":"6"}]$j$::jsonb,
