  $q$def postorder_from_pre_in(preorder: List[int], inorder: List[int]) -> List[int]$q$, $j${"python":"import sys\nfrom typing import List, Optional\n\ndef postorder_from_pre_in(preorder: List[int], inorder: List[int]) -> List[int]:\n    # Write your solution here\n    pass\n\n\ndef main():\n    it = iter(sys.stdin.read().split())\n    preorder = [int(next(it)) for _ in range(int(next(it)))]\n    inorder = [int(next(it)) for _ in range(int(next(it)))]\n    result = postorder_from_pre_in(preorder, inorder)\n    print(' '.join(map(str, result)))\n\n\nmain()\n","javascript":"const tokens = require('fs').readFileSync(0, 'utf8').split(/\\s+/).filter(Boolean);\nlet pos = 0;\nconst next = () => tokens[pos++];\n\nfunction postorderFromPreIn(preorder, inorder) {\n  // Write your solution here\n}\n\nconst preorder = Array.from({ length: parseInt(next()) }, () => parseInt(next()));\nconst inorder = Array.from({ length: parseInt(next()) }, () => parseInt(next()));\nconst result = postorderFromPreIn(preorder, inorder);\nconsole.log(result.join(' '));\n","java":"import java.util.*;\n\npublic class Main {\n    static int[] postorderFromPreIn(int[] preorder, int[] inorder) {\n        // Write your solution here\n        return new int[0];\n    }\n\n    public static void main(String[] mainArgs) {\n        Scanner scanner = new Scanner(System.in);\n        int[] preorder = new int[scanner.nextInt()];\n        for (int i = 0; i < preorder.length; i++) preorder[i] = scanner.nextInt();\n        int[] inorder = new int[scanner.nextInt()];\n        for (int i = 0; i < inorder.length; i++) inorder[i] = scanner.nextInt();\n        int[] result = postorderFromPreIn(preorder, inorder);\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < result.length; i++) {\n            if (i > 0) sb.append(' ');\n            sb.append(result[i]);\n        }\n        System.out.println(sb);\n    }\n}\n","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n\nvector<int> postorderFromPreIn(vector<int> preorder, vector<int> inorder) {\n    // Write your solution here\n    return {};\n}\n\nint main() {\n    int preorderN;\n    cin >> preorderN;\n    vector<int> preorder(preorderN);\n    for (int& x : preorder) cin >> x;\n    int inorderN;\n    cin >> inorderN;\n    vector<int> inorder(inorderN);\n    for (int& x : inorder) cin >> x;\n    auto result = postorderFromPreIn(preorder, inorder);\n    for (size_t i = 0; i < result.size(); i++) {\n        if (i) cout << ' ';\n        cout << result[i];\n    }\n    cout << endl;\n    return 0;\n}\n"}$j$::jsonb, $j$[{"input":"5\n3 9 20 15 7\n5\n9 3 15 20 7","expected":"9 15 7 20 3"},{"input":"2\n1 2\n2\n2 1","expected":"2 1"},{"input":"1\n5\n1\n5","expected":"5"},{"input":"6\n22 33 15 38 20 2\n6\n15 38 33 22 20 2","expected":"38 15 33 2 20 22"},{"input":"5\n17 22 26 32 3\n5\n26 22 17 3 32","expected":"26 22 3 32 17"},{"input":"6\n31 39 12 29 8 15\n6\n31 12 29 39 15 8","expected":"29 12 15 8 39 31"}]$j$::jsonb,
